            'SELECT l.purchase_id, l.book_id, b.title, l.quantity, l.unit_price_cents FROM purchase_line l JOIN book b ON b.id = l.book_id WHERE l.purchase_id IN (:ids) ORDER BY l.id',
            ['ids' => $purchaseIds],
            ['ids' => ArrayParameterType::INTEGER],
