{
    public function __construct(
        private readonly AuthorRepository $authors,
        private readonly BookRepository $books,
    ) {
    }

    public function provide(Operation $operation, array $uriVariables = [], array $context = []): object|array|null
    {
        /** @var Request $request */
        $request = $context['request'];

        if ($operation instanceof CollectionOperationInterface) {
            return $this->collection($request);
        }

        return $this->item($request, $uriVariables['id'] ?? '');
    }

    private function collection(Request $request): \Symfony\Component\HttpFoundation\Response
    {
        JsonApiQuery::include($request, []);
        if ([] !== JsonApiQuery::sort($request, [])) {
            throw JsonApiException::create(400, 'Authors cannot be sorted.', null, 'sort');
        }
        [$number, $size] = JsonApiQuery::page($request);

        $page = $this->authors->findPage(($number - 1) * $size, $size);
        $data = array_map(static fn (array $row): array => ResourceObjects::author($row), $page['items']);

        return JsonApiDocument::response([
            'data' => $data,
            'links' => ['self' => $request->getRequestUri()] + JsonApiQuery::pageLinks($request, $number, $size, $page['total']),
            'meta' => ['totalItems' => $page['total']],
        ]);
    }

    private function item(Request $request, string $id): \Symfony\Component\HttpFoundation\Response
    {
        $include = JsonApiQuery::include($request, ['books']);
        $authorId = self::parseId($id);
        $row = null === $authorId ? null : $this->authors->find($authorId);
        if (null === $row) {
            throw JsonApiException::create(404, 'Author not found.');
        }

        $bookRows = in_array('books', $include, true) ? $this->books->findPublishedByAuthor($authorId) : null;
        $bookIds = null === $bookRows ? null : array_map(static fn (array $book): string => (string) $book['id'], $bookRows);
        $resource = ResourceObjects::author($row, $bookIds ?? $this->bookIdsOf($authorId));

        $included = [];
        foreach ($bookRows ?? [] as $book) {
            $included[] = ResourceObjects::book($book);
        }

        return JsonApiDocument::response(JsonApiDocument::single($resource, $included));
    }

    /**
     * @return list<string>
     */
    private function bookIdsOf(int $authorId): array
    {
        return array_map(static fn (array $book): string => (string) $book['id'], $this->books->findPublishedByAuthor($authorId));
    }

    public static function parseId(string $id): ?int
    {
        return preg_match('/^[1-9][0-9]{0,9}$/', $id) && (int) $id <= 2147483647 ? (int) $id : null;
    }
