<?php
// Snapshot / restore of the rows the write tests can change, so the shared database is left as found.
function pdo(): PDO {
    static $pdo = null;
    return $pdo ??= new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
}
function db_snapshot(string $file): void {
    $p = pdo();
    $snap = [
        'books' => $p->query('SELECT id, title, price_cents, stock, published, published_at FROM book ORDER BY id')->fetchAll(PDO::FETCH_ASSOC),
        'max_purchase' => (int) $p->query('SELECT COALESCE(MAX(id),0) FROM purchase')->fetchColumn(),
        'max_line' => (int) $p->query('SELECT COALESCE(MAX(id),0) FROM purchase_line')->fetchColumn(),
        'purchase_seq' => $p->query("SELECT last_value, is_called FROM purchase_id_seq")->fetch(PDO::FETCH_ASSOC),
        'line_seq' => $p->query("SELECT last_value, is_called FROM purchase_line_id_seq")->fetch(PDO::FETCH_ASSOC),
    ];
    file_put_contents($file, json_encode($snap));
}
function db_restore(string $file): void {
    $p = pdo();
    $snap = json_decode(file_get_contents($file), true);
    $p->prepare('DELETE FROM purchase_line WHERE id > ?')->execute([$snap['max_line']]);
    $p->prepare('DELETE FROM purchase WHERE id > ?')->execute([$snap['max_purchase']]);
    $upd = $p->prepare('UPDATE book SET title = ?, price_cents = ?, stock = ?, published = ?, published_at = ? WHERE id = ?');
    foreach ($snap['books'] as $b) {
        $upd->execute([$b['title'], $b['price_cents'], $b['stock'], $b['published'] === true || $b['published'] === 't' ? 'true' : 'false', $b['published_at'], $b['id']]);
    }
    $p->prepare('SELECT setval(?, ?, ?)')->execute(['purchase_id_seq', $snap['purchase_seq']['last_value'], $snap['purchase_seq']['is_called'] === true || $snap['purchase_seq']['is_called'] === 't']);
    $p->prepare('SELECT setval(?, ?, ?)')->execute(['purchase_line_id_seq', $snap['line_seq']['last_value'], $snap['line_seq']['is_called'] === true || $snap['line_seq']['is_called'] === 't']);
}
EOF
