<?php
// Minimal HTTP client: returns [status, headers(lowercased), body].
function http(string $method, string $path, array $headers = [], ?string $body = null): array {
    $ch = curl_init('http://localhost:8089' . $path);
    $h = [];
    foreach (['Accept' => 'application/vnd.api+json'] + $headers as $k => $v) { $h[] = "$k: $v"; }
    curl_setopt_array($ch, [
        CURLOPT_CUSTOMREQUEST => $method,
        CURLOPT_HTTPHEADER => $h,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HEADERFUNCTION => function ($ch, $line) use (&$resHeaders) { $p = strpos($line, ':'); if ($p !== false) $resHeaders[strtolower(trim(substr($line, 0, $p)))] = trim(substr($line, $p + 1)); return strlen($line); },
        CURLOPT_TIMEOUT => 20,
    ]);
    $resHeaders = [];
    if ($body !== null) curl_setopt($ch, CURLOPT_POSTFIELDS, $body);
    $out = curl_exec($ch);
    $status = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    curl_close($ch);
    return [$status, $resHeaders, $out];
}
